package com.tnc.tnc.dungeon;

import com.tnc.tnc.adventure.AdventureGameTests;
import com.tnc.tnc.combat.DownedCombat;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraftforge.gametest.*;
import java.util.*;

@GameTestHolder("tncdungeon") @PrefixGameTestTemplate(false)
public final class DungeonGameTests {
 @GameTest(template="mirror_test_empty",timeoutTicks=30) public static void leavingDuringBuildRevokesDepartureBeforeExitTeleportFinishes(GameTestHelper h){var p=AdventureGameTests.player(h);var r=setup(h,1);r.members.clear();r.members.add(p.getUUID());r.leader=p.getUUID();var d=DungeonData.get(p.server);d.runs.put(r.id,r);d.profile(p.getUUID()).putUUID("Run",r.id);var pos=DungeonRealm.lobby(r).above();p.teleportTo(p.server.getLevel(DungeonRealm.KEY),pos.getX()+.5,pos.getY(),pos.getZ()+.5,0,0);var consent=Map.of(p.getUUID(),0L);h.assertTrue(DungeonService.departureValid(r,1,List.of(p),consent),"initial departure consent is valid");DungeonService.leave(p);h.assertTrue(!DungeonService.departureValid(r,1,List.of(p),consent),"leave revokes consent before asynchronous exit completes");r.closed=true;h.succeed();}
 @GameTest(template="mirror_test_empty",timeoutTicks=30) public static void reconnectAfterTeamAdvancesUsesCurrentEncounterWithoutHealingOrFreeRevive(GameTestHelper h){var p=AdventureGameTests.player(h);p.teleportTo(p.server.getLevel(DungeonRealm.KEY),100,81,100,0,0);var r=setup(h,7);r.members.add(p.getUUID());r.soloUsed.add(p.getUUID());com.tnc.tnc.dungeon.leyline.LeylineService.state(r,r.graph().rooms.get(2)).putString("Kind","NONE");r.state().started=1<<2;var d=DungeonData.get(p.server);d.runs.put(r.id,r);var profile=d.profile(p.getUUID());profile.putUUID("Run",r.id);profile.putInt("LastFloor",1);profile.putInt("LastRoom",6);p.setHealth(12);DungeonService.beginRecovery(p);h.assertTrue(DungeonService.recovering(p)&&profile.getLong("RecoverPos")==com.tnc.tnc.dungeon.leyline.LeylineService.landing(r,r.graph().rooms.get(2)).asLong()&&profile.getInt("LastFloor")==7,"recovery joins current floor, not the stale saved room");h.assertTrue(com.tnc.tnc.magic.ManaGate.shouldBlock(p,DungeonContent.id("water_ball")),"confirmation blocks actual public spell gate");DungeonService.resume(p);h.assertTrue(p.getHealth()==12&&r.soloUsed.contains(p.getUUID()),"confirmation cannot heal or refill solo allowance");r.multiplayer=true;h.assertTrue(DownedCombat.enter(p),"teammate can already be downed before reconnect");DungeonService.beginRecovery(p);h.assertTrue(DownedCombat.isDowned(p)&&!DungeonService.recovering(p)&&p.getHealth()==1,"reconnect preserves downed body and cannot grant self rescue");DownedCombat.revive(p);r.closed=true;h.succeed();}
 @GameTest(template="mirror_test_empty",timeoutTicks=30) public static void offlineCheckpointAndFullBagMailSurviveRestart(GameTestHelper h){var p=AdventureGameTests.player(h);var r=setup(h,30);var data=DungeonData.get(p.server);DungeonRewards.checkpoint(p.server,p.getUUID(),r);var profile=data.profile(p.getUUID());h.assertTrue(profile.getBoolean("Paid_desert_30")&&profile.getCompound("Reports").getLong("desert_30")==500&&profile.getInt("Trophy_desert")==1,"offline participant receives durable first-clear report and trophy entitlement");var restored=DungeonData.load(data.save(new CompoundTag()));h.assertTrue(restored.profile(p.getUUID()).getInt("Trophy_desert")==1,"mail survives NBT save and reload");for(int i=0;i<36;i++)p.getInventory().setItem(i,new ItemStack(Items.STONE,64));DungeonRewards.deliverMail(p);h.assertTrue(profile.getInt("Trophy_desert")==1,"full bag cannot discard trophy");p.getInventory().setItem(0,ItemStack.EMPTY);DungeonRewards.deliverMail(p);DungeonRewards.deliverMail(p);h.assertTrue(profile.getInt("Trophy_desert")==0&&p.getInventory().getItem(0).is(DungeonContent.ITEMS.get("dungeon_memento")),"exactly one mail delivery");h.succeed();}
 @GameTest(template="mirror_test_empty",timeoutTicks=30) public static void multiplayerDownsRepeatButSelfRescueIsNeverAllowed(GameTestHelper h){var p=AdventureGameTests.player(h);var level=p.server.getLevel(DungeonRealm.KEY);p.teleportTo(level,100.5,81,100.5,0,0);var r=setup(h,1);r.multiplayer=true;r.members.add(p.getUUID());var d=DungeonData.get(p.server);d.runs.put(r.id,r);d.profile(p.getUUID()).putUUID("Run",r.id);for(int i=0;i<20;i++){h.assertTrue(DownedCombat.enter(p)&&DownedCombat.isDowned(p),"multiplayer can down again "+i);h.assertTrue(!DownedCombat.canRescue(p,p),"no multiplayer self rescue "+i);DownedCombat.revive(p);}h.assertTrue(r.soloUsed.isEmpty(),"teammate revives never consume solo allowance");r.closed=true;h.succeed();}
 private static DungeonData.Run setup(GameTestHelper h,int floor){var p=AdventureGameTests.player(h);var r=new DungeonData.Run(UUID.randomUUID(),p.getUUID(),h.getLevel().random.nextLong(),700+Math.abs(p.getUUID().hashCode()%40),DungeonTheme.DESERT);r.floor=floor;return r;}
 @GameTest(template="mirror_test_empty",timeoutTicks=30) public static void ledgerRoundtripPreservesInstanceRoomsClaimsAndSoloChance(GameTestHelper h){var d=new DungeonData();var r=setup(h,7);r.multiplayer=true;r.soloUsed.add(r.leader);r.state().cleared=7;r.state().claims.putBoolean("unique",true);r.state().enemies.put("3",new CompoundTag());d.runs.put(r.id,r);d.profile(r.leader).putLong("Saved",70);d.profile(r.leader).putLong("Pending",30);var loaded=DungeonData.load(d.save(new CompoundTag()));var rr=loaded.runs.get(r.id);h.assertTrue(rr.multiplayer&&rr.soloUsed.contains(r.leader)&&rr.state().cleared==7&&rr.state().claims.getBoolean("unique")&&loaded.profile(r.leader).getLong("Saved")==70,"durable progress, claims, party mode and down allowance");h.assertTrue(DungeonData.failureLoss(30)==6&&DungeonData.failureLoss(4)==0,"only twenty percent pending tokens at risk");h.succeed();}
 @GameTest(template="mirror_test_empty",timeoutTicks=30) public static void allMobFamiliesCreateWithRealAttributesAndGuardianHitboxes(GameTestHelper h){for(var s:MobCatalog.ALL){var m=DungeonContent.MOBS.get(s.id()).create(h.getLevel());h.assertTrue(m!=null,"registered "+s.id());m.configure(20,2,false);h.assertTrue(m.getMaxHealth()>s.health()&&m.species().id().equals(s.id()),"real scaled attributes "+s.id());float small=m.getBbHeight();m.guardian(true);h.assertTrue(m.getBbHeight()>small*1.7,"guardian grows collision as well as renderer");var tag=new CompoundTag();m.save(tag);var read=EntityType.loadEntityRecursive(tag,h.getLevel(),x->x);h.assertTrue(read instanceof DungeonMob d&&d.guardian(),"entity NBT roundtrip");}h.succeed();}
 @GameTest(template="mirror_test_empty",timeoutTicks=40) public static void realmTerrainRejectsDirectSpellWritesButBuilderWorks(GameTestHelper h){var l=h.getLevel().getServer().getLevel(DungeonRealm.KEY);h.assertTrue(l!=null,"real dimension loaded from datapack");var p=new BlockPos(10,80,10);l.getChunkAt(p);DungeonRealm.write(()->l.setBlock(p,Blocks.STONE.defaultBlockState(),2));h.assertTrue(l.getBlockState(p).is(Blocks.STONE),"builder can write");h.assertTrue(!l.setBlock(p,Blocks.AIR.defaultBlockState(),2)&&l.getBlockState(p).is(Blocks.STONE),"direct spell writes cannot carve shell");DungeonRealm.write(()->l.setBlock(p,Blocks.AIR.defaultBlockState(),2));h.succeed();}
 @GameTest(template="mirror_test_empty",timeoutTicks=30) public static void fourThemesContainPortalAssetAnchorsAndNoUnknownNamespaces(GameTestHelper h){for(var t:DungeonTheme.values()){var a=DungeonGateAssets.get(t);h.assertTrue(!a.pieces().isEmpty()&&a.size().getY()>50,"actual imported original gate: "+t.id);h.assertTrue(a.portal().getY()>=1&&a.portal().getY()<a.size().getY(),"valid portal anchor");for(var p:a.pieces())h.assertTrue(h.getLevel().getStructureManager().get(p.resource()).isPresent(),"all native slices exist");}h.succeed();}
 @GameTest(template="mirror_test_empty",timeoutTicks=30) public static void actualFloorGeometryHasEightRoomsAndDoorsForEveryEdge(GameTestHelper h){for(var theme:DungeonTheme.values()){var r=setup(h,5);r.theme=theme;var cells=DungeonRealm.floorCells(r);h.assertTrue(cells.size()>15000&&cells.size()<100000,"bounded procedural building budget");var map=new HashMap<BlockPos,net.minecraft.world.level.block.state.BlockState>();cells.forEach(c->map.put(c.pos(),c.state()));for(var room:r.graph().rooms){var center=DungeonRealm.center(r,room);var landing=com.tnc.tnc.dungeon.leyline.LeylineService.landing(r,room);h.assertTrue(map.containsKey(landing.below())&&!map.get(landing.below()).isAir(),"supported room recovery entrance");h.assertTrue(map.getOrDefault(landing,Blocks.AIR.defaultBlockState()).isAir()&&map.getOrDefault(landing.above(),Blocks.AIR.defaultBlockState()).isAir(),"unobstructed recovery entrance");for(int dest:room.links())for(var door:DungeonRealm.door(r,room,dest))h.assertTrue(map.get(door).isAir(),"every graph edge has a physically open door");}}h.succeed();}
 @GameTest(template="mirror_test_empty",timeoutTicks=30) public static void oldRoomCursorCannotSkipNewRunStart(GameTestHelper h){var p=AdventureGameTests.player(h);var d=DungeonData.get(p.server);var r=setup(h,1);r.members.clear();r.members.add(p.getUUID());r.leader=p.getUUID();d.runs.put(r.id,r);var t=d.profile(p.getUUID());t.putUUID("Run",r.id);t.putUUID("CursorRun",UUID.randomUUID());t.putInt("LastFloor",1);t.putInt("LastRoom",5);h.assertTrue(DungeonService.validateRoom(p,r,r.graph().rooms.get(0))&&t.getInt("LastRoom")==0&&t.getUUID("CursorRun").equals(r.id),"new run resets old floor cursor");r.closed=true;h.succeed();}
 @GameTest(template="mirror_test_empty",timeoutTicks=30) public static void cacheClaimIsAtomicAtFullInventoryAndCannotPayTwice(GameTestHelper h){var p=AdventureGameTests.player(h);var r=setup(h,1);var room=r.graph().rooms.stream().filter(a->a.kind()==DungeonGraph.Kind.TREASURE).findFirst().orElseThrow();for(int i=0;i<36;i++)p.getInventory().setItem(i,new ItemStack(Items.STONE,64));h.assertTrue(!DungeonRewards.claim(p,r,room)&&!DungeonRewards.claimRecord(r.state(),room.id()).getBoolean(p.getUUID().toString()),"full bag preserves claim");p.getInventory().clearContent();h.assertTrue(DungeonRewards.claim(p,r,room),"space accepts actual materials");long balance=DungeonData.get(p.server).profile(p.getUUID()).getLong("Pending");h.assertTrue(!DungeonRewards.claim(p,r,room)&&DungeonData.get(p.server).profile(p.getUUID()).getLong("Pending")==balance,"repeat packet cannot pay again");h.succeed();}
 @GameTest(template="mirror_test_empty",timeoutTicks=30) public static void encounterCannotSealWhenTeamIsOutside(GameTestHelper h){var p=AdventureGameTests.player(h);var r=setup(h,1);p.setPos(0,70,0);h.assertTrue(!DungeonService.startRoom(h.getLevel(),r,r.graph().rooms.get(0),List.of(p))&&r.state().started==0,"party distance verified in shared start method");h.succeed();}
 @GameTest(template="mirror_test_empty",timeoutTicks=60) public static void monsterDeathActuallyClearsRegisteredWave(GameTestHelper h){var r=setup(h,1);r.slot=0;var p=AdventureGameTests.player(h);var room=r.graph().rooms.stream().filter(a->a.kind()==DungeonGraph.Kind.COMBAT&&a.layout()!=1).findFirst().orElseThrow();com.tnc.tnc.dungeon.leyline.LeylineService.state(r,room).putString("Kind","NONE");var center=DungeonRealm.center(r,room);p.setPos(center.getX()+.5,81,center.getZ()+.5);h.getLevel().getChunkAt(center);var d=DungeonData.get(p.server);d.runs.put(r.id,r);h.assertTrue(DungeonService.startRoom(h.getLevel(),r,room,List.of(p)),"starts legal encounter");DungeonService.checkRoom(h.getLevel(),r,room,List.of(p),p.server.overworld().getGameTime()+30);var enemies=r.state().enemies.getCompound(Integer.toString(room.id()));h.assertTrue(!enemies.isEmpty(),"actual mob spawns recorded");for(String id:new HashSet<>(enemies.getAllKeys())){var mob=h.getLevel().getEntity(UUID.fromString(id));h.assertTrue(mob instanceof DungeonMob,"real registered enemy");((DungeonMob)mob).hurt(h.getLevel().damageSources().genericKill(),100000);}DungeonService.checkRoom(h.getLevel(),r,room,List.of(p),p.server.overworld().getGameTime()+40);h.assertTrue(r.state().clear(room.id()),"real kills clear room");r.closed=true;h.succeed();}
 @GameTest(template="mirror_test_empty",timeoutTicks=30) public static void separateInstancesNeverShareRescueGroups(GameTestHelper h){var a=AdventureGameTests.player(h);var b=AdventureGameTests.player(h);var d=DungeonData.get(a.server);var ra=setup(h,1);var rb=setup(h,1);ra.members.clear();ra.members.add(a.getUUID());rb.members.clear();rb.members.add(b.getUUID());d.runs.put(ra.id,ra);d.runs.put(rb.id,rb);d.profile(a.getUUID()).putUUID("Run",ra.id);d.profile(b.getUUID()).putUUID("Run",rb.id);h.assertTrue(!ra.id.equals(rb.id)&&!ra.members.contains(b.getUUID()),"explicit members not global co-op fallback");h.assertTrue(DungeonService.takeSoloDown(a)&&!DungeonService.takeSoloDown(a),"one solo allowance per segment");rb.multiplayer=true;h.assertTrue(!DungeonService.takeSoloDown(b),"multiplayer cannot self revive");ra.closed=true;rb.closed=true;h.succeed();}
}
